"""5-method causal analysis for generalize experiments.

Reuses the same statistical methods as cross_alpha_analysis_v4.py
but targets results/generalize/{experiment}/all_metrics.json.

Usage:
    python analyze_generalize.py --exp pythia410m_wiki_a100_s42
    python analyze_generalize.py --exp opt1b_wiki_a100_s42
    python analyze_generalize.py  # all experiments in results/generalize/
"""

import argparse
import json
import os
import sys
import warnings
from datetime import datetime

import numpy as np
from statsmodels.stats.multitest import multipletests

warnings.filterwarnings("ignore")

BASE_DIR = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, BASE_DIR)

from method_ablation import (
    CANARY, DOWNSTREAM,
    extract as ma_extract,
    naive_pearson, diff_xcorr, threshold_lead, toda_yamamoto, perm_granger,
)

GENERALIZE_DIR = os.path.join(BASE_DIR, "results", "generalize")

MA_METHODS = {
    "naive_pearson": naive_pearson,
    "differenced_xcorr": diff_xcorr,
    "threshold_onset": threshold_lead,
    "toda_yamamoto": toda_yamamoto,
    "permutation_granger": perm_granger,
}

METRICS = ["distinct_1", "distinct_2", "distinct_3",
           "token_entropy", "ece", "perplexity"]

class NumpyEncoder(json.JSONEncoder):
    def default(self, obj):
        if isinstance(obj, (np.integer,)):
            return int(obj)
        if isinstance(obj, (np.floating,)):
            return float(obj)
        if isinstance(obj, np.ndarray):
            return obj.tolist()
        return super().default(obj)


def assemble_all_metrics(exp_dir):
    """Assemble all_metrics.json from per-gen metrics.json if needed."""
    all_path = os.path.join(exp_dir, "all_metrics.json")
    if os.path.exists(all_path):
        with open(all_path) as f:
            return json.load(f)

    metrics = []
    gen_idx = 0
    while True:
        gen_dir = os.path.join(exp_dir, f"gen_{gen_idx}")
        mpath = os.path.join(gen_dir, "metrics.json")
        if not os.path.exists(mpath):
            break
        with open(mpath) as f:
            m = json.load(f)
        m["generation"] = gen_idx
        metrics.append(m)
        gen_idx += 1

    if not metrics:
        return None
    return sorted(metrics, key=lambda x: x["generation"])


def compute_drift(metrics_list):
    result = {}
    for metric in METRICS:
        vals = [m[metric] for m in metrics_list]
        gen0, genN = vals[0], vals[-1]
        drift_pct = round((genN - gen0) / abs(gen0) * 100, 2) if abs(gen0) > 1e-12 else 0.0
        result[metric] = {
            "gen0": round(gen0, 6),
            f"gen{len(vals)-1}": round(genN, 6),
            "drift_pct": drift_pct,
        }
    return result


def run_5method(metrics_list, n_perm=1000):
    pairs_results = {}
    all_p_values = []
    p_value_keys = []

    for cn in CANARY:
        for dn in DOWNSTREAM:
            pair_key = f"{cn}->{dn}"
            c = ma_extract(metrics_list, cn)
            d = ma_extract(metrics_list, dn)

            pair = {}
            for method_name, method_fn in MA_METHODS.items():
                try:
                    res = method_fn(c, d, cn, dn)
                except Exception as e:
                    res = {"error": str(e)}
                pair[method_name] = res

                p = res.get("p_value") or res.get("p_raw")
                if p is not None:
                    all_p_values.append(p)
                    p_value_keys.append((pair_key, method_name))

            pairs_results[pair_key] = pair

    if all_p_values:
        _, fdr_ps, _, _ = multipletests(all_p_values, method="fdr_bh")
        for i, (pk, mn) in enumerate(p_value_keys):
            pairs_results[pk][mn]["p_fdr"] = round(float(fdr_ps[i]), 6)

    return pairs_results


def summarize_votes(pairs_results):
    summary = {}
    for pair_key, methods in pairs_results.items():
        votes = {}
        for method_name, res in methods.items():
            if "error" in res:
                votes[method_name] = "error"
                continue
            sig = res.get("significant", res.get("p_fdr", res.get("p_value", 1.0)))
            if isinstance(sig, bool):
                votes[method_name] = "significant" if sig else "not_significant"
            elif isinstance(sig, (int, float)):
                votes[method_name] = "significant" if sig < 0.05 else "not_significant"
            else:
                votes[method_name] = str(sig)
        summary[pair_key] = votes
    return summary


def analyze_experiment(exp_name, exp_dir):
    config_path = os.path.join(exp_dir, "config.json")
    config = {}
    if os.path.exists(config_path):
        with open(config_path) as f:
            config = json.load(f)

    metrics_list = assemble_all_metrics(exp_dir)
    if metrics_list is None:
        return {"experiment": exp_name, "status": "no_metrics", "error": "No metrics found"}

    n_gens = len(metrics_list)
    print(f"  {exp_name}: {n_gens} generations", flush=True)

    drift = compute_drift(metrics_list)
    pairs_results = run_5method(metrics_list)
    votes = summarize_votes(pairs_results)

    n_sig = sum(1 for pair_votes in votes.values()
                for v in pair_votes.values() if v == "significant")
    n_total = sum(1 for pair_votes in votes.values()
                  for v in pair_votes.values() if v != "error")

    return {
        "experiment": exp_name,
        "model": config.get("model_name", "unknown"),
        "dataset": config.get("dataset", "unknown"),
        "alpha": config.get("synthetic_ratio", None),
        "seed": config.get("seed", None),
        "n_generations": n_gens,
        "status": "complete" if n_gens >= 10 else f"partial_{n_gens}gen",
        "drift": drift,
        "five_method_analysis": pairs_results,
        "vote_summary": votes,
        "sig_rate": f"{n_sig}/{n_total}",
        "timestamp": datetime.now().isoformat(),
    }


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--exp", type=str, default=None,
                        help="Specific experiment name (subdirectory of results/generalize/)")
    parser.add_argument("--n_perm", type=int, default=1000)
    args = parser.parse_args()

    if args.exp:
        experiments = [args.exp]
    else:
        experiments = sorted(d for d in os.listdir(GENERALIZE_DIR)
                           if os.path.isdir(os.path.join(GENERALIZE_DIR, d)))

    all_results = {}
    for exp_name in experiments:
        exp_dir = os.path.join(GENERALIZE_DIR, exp_name)
        if not os.path.isdir(exp_dir):
            print(f"  {exp_name}: directory not found, skipping", flush=True)
            continue
        print(f"Analyzing {exp_name}...", flush=True)
        result = analyze_experiment(exp_name, exp_dir)
        all_results[exp_name] = result

    out_dir = os.path.join(GENERALIZE_DIR, "analysis")
    os.makedirs(out_dir, exist_ok=True)
    out_path = os.path.join(out_dir, "generalize_5method_results.json")
    with open(out_path, "w") as f:
        json.dump(all_results, f, indent=2, cls=NumpyEncoder)
    print(f"\nResults saved to {out_path}", flush=True)

    for exp_name, result in all_results.items():
        print(f"\n{'='*60}")
        print(f"{exp_name} ({result.get('model', '?')}, {result.get('status', '?')})")
        print(f"  Sig rate: {result.get('sig_rate', '?')}")
        if "drift" in result:
            for m in ["distinct_1", "token_entropy", "ece"]:
                d = result["drift"].get(m, {})
                print(f"  {m}: {d.get('drift_pct', '?')}% drift")


if __name__ == "__main__":
    main()
